function selectDashboardNode(id){selectedDashboardNode=id;const sel=latestNodes.find(n=>n.id===id);const detailEl=document.getElementById('dashboardDetail');if(detailEl)detailEl.innerHTML=sel?dashboardCard(sel):'';document.querySelectorAll('#dashboardSummary .miniCard').forEach(el=>el.classList.toggle('active',Number(el.dataset.id)===id))}
function rememberChartInspection(){return Array.from(document.querySelectorAll('svg[data-node]')).filter(svg=>svg.querySelector('[data-inspector]')?.getAttribute('visibility')==='visible').map(svg=>({node:svg.dataset.node,parent:svg.closest('.nodeCard')?.parentElement.id,index:Number(svg.dataset.selected),x:svg.dataset.pointerX,y:svg.dataset.pointerY,focused:document.activeElement===svg}));}
function restoreChartInspection(saved){for(const s of saved){const svg=document.getElementById(s.parent)?.querySelector(`svg[data-node="${s.node}"]`);if(!svg)continue;if(s.x!==undefined)chartHover({clientX:Number(s.x),clientY:Number(s.y)},svg);else chartSelect(svg,s.index);if(s.focused)svg.focus({preventScroll:true});}}
function cToF(c){return c*9/5+32}
function mapRecent(d){const now=Date.now();return (d.points||[]).map(a=>({at:now-a[0]*1000,ageSeconds:a[0],volts:a[1]/1000,tempF:a[2]==null?null:cToF(a[2]/10),humidityRh:a[3]==null?null:a[3]/10,externalTempF:a[4]==null?null:cToF(a[4]/10),externalTempStatus:a[5],rssi:a[6],sequence:a[7],status:STATUS_CODES[a[8]]||'UNKNOWN'}))}
function mapHourly(d,hours){const now=d.now&&d.now>1700000000?d.now:Math.floor(Date.now()/1000);const endHour=Math.floor(now/3600),startHour=endHour-hours+1;const byHour=new Map((d.points||[]).map(a=>[Math.floor(a[0]/3600),a]));let first=null;for(let hr=startHour;hr<=endHour;hr++)if(byHour.has(hr)){first=hr;break}if(first===null)return [];const out=[];for(let hr=first;hr<=endHour;hr++){const a=byHour.get(hr),at=hr*3600000;out.push(a?{at,hourly:true,volts:a[1]/1000,vmin:a[2]/1000,vmax:a[3]/1000,tempF:a[4]==null?null:cToF(a[4]/10),externalTempF:a[5]==null?null:cToF(a[5]/10),rssi:a[6],count:a[7]}:{at,hourly:true,empty:true,volts:null,tempF:null,externalTempF:null,rssi:null})}return out}
function refreshAges(){const now=Date.now();const fix=arr=>{for(const p of arr||[])if(p.at)p.ageSeconds=Math.max(0,Math.round((now-p.at)/1000))};Object.values(histories).forEach(fix);Object.values(rangeHist).forEach(r=>Object.values(r).forEach(fix))}
function chartData(n){return chartRange==='recent'?(histories[n.id]||[]):(rangeHist[chartRange][n.id]||[])}
function chartCount(h){return h.length&&h[0].hourly?h.filter(p=>!p.empty).length:h.length}
function rangeName(){return (RANGE_LABELS.find(r=>r[0]===chartRange)||RANGE_LABELS[0])[1]}
function rangePicker(){return `<div class="rangePick" role="group" aria-label="Graph range">${RANGE_LABELS.map(([k,l])=>`<button type="button" class="${k===chartRange?'on':''}" aria-pressed="${k===chartRange}" onclick="setChartRange('${k}')">${l}</button>`).join('')}</div>`}
function renderRangePickers(){const el=document.getElementById('historyRangePick');if(el)el.innerHTML=rangePicker()}
function setChartRange(k){if(k===chartRange)return;chartRange=k;try{localStorage.setItem('sentinelChartRange',k)}catch(e){}renderRangePickers();renderDashboardCards();const hn=document.getElementById('historyNodes');if(hn&&latestNodes.length)hn.innerHTML=latestNodes.map(historyCard).join('');refresh()}
function emptyHistoryText(n){if(chartRange==='recent')return `<div>Collecting history — no readings received since the Hub restarted</div>`;if(!rangeAvail)return '<div>Hourly history starts once the Hub has set its clock from the internet (a minute or two after it joins Wi-Fi).</div>';const key=chartRange+':'+n.id;return rangeRev[key]===undefined?'<div>Loading…</div>':`<div>No hourly readings for this device in the last ${rangeName().toLowerCase()} yet.</div>`}
function fmtHour(ms){const d=new Date(ms);return d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})+', '+d.toLocaleTimeString(undefined,{hour:'numeric'})}
function hourlyTip(p,hasExternal,hasTemp){if(p.empty)return [fmtHour(p.at),'No readings this hour'].join(' | ');return [`${fmtHour(p.at)} · ${p.count} reading${p.count===1?'':'s'}`,Number.isFinite(p.volts)?`Voltage: ${p.volts.toFixed(2)} V avg (${p.vmin.toFixed(2)}–${p.vmax.toFixed(2)})`:'Voltage: unavailable',...(hasExternal?[Number.isFinite(p.externalTempF)?`External probe: ${p.externalTempF.toFixed(1)} °F avg`:'External probe: unavailable']:[]),...(hasTemp?[Number.isFinite(p.tempF)?`Onboard (SHT40): ${p.tempF.toFixed(1)} °F avg`:'Onboard (SHT40): unavailable']:[]),Number.isFinite(p.rssi)?`Signal: ${p.rssi} dBm avg`:'Signal: unavailable'].join(' | ')}
function axisLeft(h){if(!h.length||!h[0].hourly)return 'oldest';const d=new Date(h[0].at);return d.toLocaleDateString(undefined,{month:'short',day:'numeric'})+(chartRange==='24h'?' '+d.toLocaleTimeString(undefined,{hour:'numeric'}):'')}
function axisRight(h){return h.length&&h[0].hourly?'now':'newest'}
function voltBand(h,vr,left,right,top,bottom){if(!h.length||!h[0].hourly)return '';const X=i=>(left+(i/Math.max(1,h.length-1))*(right-left)).toFixed(1);const Y=v=>(bottom-((v-vr.lo)/(vr.hi-vr.lo))*(bottom-top)).toFixed(1);let d='',run=[];const flush=()=>{if(run.length>1)d+='M'+run.map(i=>X(i)+','+Y(h[i].vmax)).join('L')+'L'+run.slice().reverse().map(i=>X(i)+','+Y(h[i].vmin)).join('L')+'Z';run=[]};h.forEach((p,i)=>{if(Number.isFinite(p.vmin)&&Number.isFinite(p.vmax))run.push(i);else flush()});flush();return d?`<path d="${d}" fill="rgba(56,217,150,.16)" stroke="none"><title>Hourly low–high voltage</title></path>`:''}
